/**
 * Auth contract (SPEC 13 §7, SPEC 13b §3): email rules, password rules, the request bodies of `/v1/auth/*` and the
 * session answer. Every auth request names the `app` (client or provider): an email belongs to one side only, and the
 * other side is refused with `wrong_side` and that side's message (WRONG_SIDE_MESSAGES).
 */
import { z } from "zod";
import type { ApiResult, Client } from "./client";
import { asciiDigits } from "./digits";
import { LIMITS } from "./limits";
import { codePoints, optionalText, text, visibleText } from "./text";
import { type Me, meSchema, requiredString } from "./me";

export const APP_SIDES = ["client", "provider"] as const;
export type AppSide = (typeof APP_SIDES)[number];
export const SESSION_PLATFORMS = ["ios", "android", "web"] as const;
export type SessionPlatform = (typeof SESSION_PLATFORMS)[number];

/** What each app says to an email that belongs to the other side (owner rule 2026-10-21, carried over from v1). */
export const WRONG_SIDE_MESSAGES: Record<AppSide, string> = {
  provider: "This email is registered as a customer account. Use a different email for your provider account.",
  client: "This email is registered as a provider account. Use a different email to book services.",
};

// ---- email ----

export const EMAIL_MAX = 254;
/** Control characters, zero-width and other invisible format characters, bidi controls. */
const EMAIL_FORBIDDEN = /[\p{Cc}\p{Cf}\u034F\u115F\u1160\u180E\u2028\u2029\u3164\uFFA0]/u;
/**
 * RFC 5321 dot-atom local part (ASCII letters, digits and the atext symbols, dots only between them) @ a domain of
 * labels (letters of any script, digits, inner hyphens) with a 2+ letter last label. No quotes, commas, angle brackets
 * or parentheses, so an address can never smuggle a second recipient or a display name.
 */
const ATEXT = "[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+";
const LABEL = "[\\p{L}\\p{N}](?:[\\p{L}\\p{N}-]*[\\p{L}\\p{N}])?";
const EMAIL_SHAPE = new RegExp(`^${ATEXT}(?:\\.${ATEXT})*@(?:${LABEL}\\.)+\\p{L}{2,}$`, "u");

/** trim, Unicode NFKC, lower case. */
export const normalizeEmail = (raw: string): string => raw.trim().normalize("NFKC").toLowerCase();

/** Why an (already normalised) address is refused, or null. */
export function emailProblem(email: string): string | null {
  if (email === "") return "Enter your email address.";
  if (EMAIL_FORBIDDEN.test(email)) return "Remove the hidden or special characters from your email address.";
  if (codePoints(email) > EMAIL_MAX) return `Use ${EMAIL_MAX} characters or fewer.`;
  if (!EMAIL_SHAPE.test(email)) return "Enter a valid email address.";
  return null;
}

/** Domains whose mailboxes ignore dots in the local part (one service under two names). */
const DOTLESS_DOMAINS = new Set(["gmail.com", "googlemail.com"]);

/**
 * The inbox behind an address (the alias rule): the `+tag` removed (providers deliver a +tag to the same inbox), and
 * for Gmail also the dots of the local part (Gmail ignores them; googlemail.com is gmail.com). Other providers treat
 * dots as real (`john.smith@outlook.com` and `johnsmith@outlook.com` are two people), so their dots stay.
 */
export function canonicalEmail(email: string): string {
  const e = normalizeEmail(email);
  const at = e.lastIndexOf("@");
  if (at < 0) return e;
  let local = e.slice(0, at).split("+", 1)[0]!;
  let domain = e.slice(at + 1);
  if (DOTLESS_DOMAINS.has(domain)) {
    local = local.replaceAll(".", "");
    domain = "gmail.com";
  }
  return `${local}@${domain}`;
}

/** v1's words (auth_email.ALIAS_TAKEN) for a first sign-in under another spelling of an inbox that has an account. */
export const ALIAS_TAKEN_MESSAGE = "An account already exists for this inbox (dots and +tags do not make a new address). Sign in with the address you used before.";

export const emailSchema = z
  .string({ error: (iss) => (iss.input === undefined ? "Enter your email address." : "Enter a valid email address.") })
  .refine((v) => v.length <= 1000, "Enter a valid email address.")
  .transform(normalizeEmail)
  .superRefine((e, ctx) => {
    const problem = emailProblem(e);
    if (problem) ctx.addIssue({ code: "custom", message: problem });
  });

// ---- password ----

export const PASSWORD = { min: 8, max: 128 } as const;
/** What the forms say up front. */
export const PASSWORD_RULES = "Use 8 to 128 characters. Avoid common passwords and your email address.";

/** The most common passwords of at least 8 characters (refused outright). */
const COMMON_PASSWORDS = new Set([
  "12345678",
  "123456789",
  "1234567890",
  "123123123",
  "11111111",
  "00000000",
  "87654321",
  "password",
  "password1",
  "password123",
  "passw0rd",
  "qwertyui",
  "qwerty123",
  "qwertyuiop",
  "iloveyou",
  "abcd1234",
  "abc12345",
  "1q2w3e4r",
  "1qaz2wsx",
  "zaq12wsx",
  "sunshine",
  "princess",
  "football",
  "baseball",
  "welcome1",
  "letmein1",
  "trustno1",
  "superman",
  "asdfghjkl",
  "phriend1",
  "phriend123",
  "iloveyou1",
  "mahalkita",
  "pilipinas",
  "philippines",
]);

/** Why a password is refused (user-ready), or null. `email` (normalised) is compared case-insensitively. */
export function passwordProblem(password: string, email?: string): string | null {
  const n = codePoints(password);
  if (n < PASSWORD.min) return `Use at least ${PASSWORD.min} characters.`;
  if (n > PASSWORD.max) return `Use ${PASSWORD.max} characters or fewer.`;
  if (/\p{Cc}/u.test(password)) return "Remove the special characters from your password.";
  if (visibleText(password).length === 0) return "Use letters, numbers or symbols in your password.";
  const lower = password.toLowerCase();
  if (COMMON_PASSWORDS.has(lower) || /^(.)\1+$/u.test(password)) return "This password is too common. Choose another one.";
  if (email && (lower === email || lower === email.split("@")[0])) return "Your password can't be your email address.";
  return null;
}

const passwordString = z.string({ error: "Enter a password." }).refine((v) => v.length <= 4096, `Use ${PASSWORD.max} characters or fewer.`);

/** A new password (sign-up, reset): the rules above. The email check runs on the whole body (see `withPasswordRules`). */
export const newPasswordSchema = passwordString.superRefine((p, ctx) => {
  const problem = passwordProblem(p);
  if (problem) ctx.addIssue({ code: "custom", message: problem });
});

// ---- shared pieces ----

export const appSideSchema = z.enum(APP_SIDES, { error: "Choose the client or the provider app." });

/**
 * The device a session belongs to. Signed-in devices and the new sign-in email show a label the API builds from the
 * app, its version and the platform ("Phriend 2.0.0 on iPhone", "a web browser"), never client text, so a sign-in
 * cannot dress itself up as the member's own phone.
 */
export const deviceInfoSchema = z.strictObject({
  platform: z.enum(SESSION_PLATFORMS, { error: "Choose ios, android or web." }),
});
export type DeviceInfo = z.output<typeof deviceInfoSchema>;

/** A 6-digit code as typed (spaces and other digit scripts allowed). */
export const authCodeSchema = z
  .string({ error: "Enter the 6-digit code from your email." })
  .refine((v) => v.length <= 40, "Enter the 6-digit code from your email.")
  .transform((s) => asciiDigits(s).replace(/[\s-]/g, ""))
  .refine((s) => /^\d{6}$/.test(s), "Enter the 6-digit code from your email.");

/** A sign-up name: the display name rules (client 1-30, provider 2-30). */
const signupName = text(LIMITS.clientDisplayName, { noEmoji: true, reserved: "display_name" });

/** A password as typed at sign-in (any non-empty text up to the cap; the rules apply when one is chosen). */
const enteredPassword = passwordString.refine((v) => v.length > 0, "Enter your password.");

/**
 * The raw nonce the app made for this sign-in (16-256 visible ASCII characters). Google's ID token carries it as it
 * is; Apple's carries its SHA-256 in lower-case hex (hand `sha256(rawNonce)` to Apple, send the raw one here). A nonce
 * works once, so a leaked ID token cannot be replayed.
 */
export const nonceSchema = requiredString("The sign-in nonce is required.", 256, "The sign-in nonce is too long.")
  .refine((v) => v.length >= 16, "The sign-in nonce is too short.")
  .refine((v) => /^[\x21-\x7e]*$/.test(v), "The sign-in nonce isn't valid.");

// ---- request bodies ----

export const signupBodySchema = z
  .strictObject({ app: appSideSchema, name: signupName, email: emailSchema, password: newPasswordSchema })
  .superRefine((b, ctx) => {
    if (b.app === "provider" && codePoints(visibleText(b.name)) < LIMITS.displayName.min) ctx.addIssue({ code: "custom", path: ["name"], message: `Use at least ${LIMITS.displayName.min} characters.` });
    const problem = passwordProblem(b.password, b.email);
    if (problem) ctx.addIssue({ code: "custom", path: ["password"], message: problem });
  });
export type SignupBody = z.output<typeof signupBodySchema>;

export const loginBodySchema = z.strictObject({
  app: appSideSchema,
  email: emailSchema,
  password: enteredPassword,
  device: deviceInfoSchema,
});
export type LoginBody = z.output<typeof loginBodySchema>;

export const CODE_PURPOSES = ["verify", "reset"] as const;
export type CodePurpose = (typeof CODE_PURPOSES)[number];

export const codesBodySchema = z.strictObject({ email: emailSchema, purpose: z.enum(CODE_PURPOSES, { error: "Choose verify or reset." }) });
export type CodesBody = z.output<typeof codesBodySchema>;

/**
 * The sign-up code. `password` is the one chosen at sign-up: the account is created only when the code (proof of the
 * inbox) and that password (proof of the sign-up) both match, so a stranger's repeat sign-up cannot set it.
 */
export const verifyEmailBodySchema = z.strictObject({ email: emailSchema, code: authCodeSchema, password: enteredPassword, app: appSideSchema, device: deviceInfoSchema });
export type VerifyEmailBody = z.output<typeof verifyEmailBodySchema>;

export const passwordResetBodySchema = z
  .strictObject({ email: emailSchema, code: authCodeSchema, password: newPasswordSchema, app: appSideSchema, device: deviceInfoSchema })
  .superRefine((b, ctx) => {
    const problem = passwordProblem(b.password, b.email);
    if (problem) ctx.addIssue({ code: "custom", path: ["password"], message: problem });
  });
export type PasswordResetBody = z.output<typeof passwordResetBodySchema>;

const idToken = (what: string) => requiredString(`${what} is required.`, 4096, `${what} is too long.`);

export const googleBodySchema = z.strictObject({ app: appSideSchema, idToken: idToken("The Google token"), nonce: nonceSchema, device: deviceInfoSchema });
export type GoogleBody = z.output<typeof googleBodySchema>;

const namePart = optionalText({ min: 0, max: 60 });
/** Apple's name parts as `expo-apple-authentication` hands them over (only on the first sign-in). */
export const appleFullNameSchema = z.strictObject({ givenName: namePart, familyName: namePart, middleName: namePart, nickname: namePart, namePrefix: namePart, nameSuffix: namePart });

export const appleBodySchema = z.strictObject({
  app: appSideSchema,
  identityToken: idToken("The Apple token"),
  nonce: nonceSchema,
  authorizationCode: requiredString("The Apple authorization code is required.", 1024, "The Apple authorization code is too long."),
  fullName: appleFullNameSchema.nullish(),
  device: deviceInfoSchema,
});
export type AppleBody = z.output<typeof appleBodySchema>;

// ---- responses ----

export const signupResponseSchema = z.object({ verificationRequired: z.literal(true) });
export type SignupResponse = z.output<typeof signupResponseSchema>;

/** Every sign-in answers the opaque session token (keep it in secure storage or the BFF cookie) and the bootstrap `me`. */
export const sessionResponseSchema = z.object({ token: z.string(), me: meSchema });
export type SessionResponse = { token: string; me: Me };

export const socialSessionResponseSchema = sessionResponseSchema.extend({ created: z.boolean() });
export type SocialSessionResponse = SessionResponse & { created: boolean };

/** `POST /v1/auth/codes`: always this, whether or not the email has an account. */
export const codesResponseSchema = z.object({ ok: z.literal(true) });
/** A 204 (no body). */
export const noContentSchema = z.undefined();

// ---- typed client ----

/** In: the request body. The zod input type (before normalisation). */
type In<S extends z.ZodType> = z.input<S>;

export function authApi(api: Client) {
  return {
    signup: (body: In<typeof signupBodySchema>): Promise<ApiResult<SignupResponse>> => api.post("/v1/auth/signup", body, { schema: signupResponseSchema }),
    login: (body: In<typeof loginBodySchema>): Promise<ApiResult<SessionResponse>> => api.post("/v1/auth/login", body, { schema: sessionResponseSchema }),
    /** Always 202, whether or not the email has an account. */
    requestCode: (body: In<typeof codesBodySchema>): Promise<ApiResult<{ ok: true }>> => api.post("/v1/auth/codes", body, { schema: codesResponseSchema }),
    verifyEmail: (body: In<typeof verifyEmailBodySchema>): Promise<ApiResult<SessionResponse>> => api.post("/v1/auth/verify-email", body, { schema: sessionResponseSchema }),
    resetPassword: (body: In<typeof passwordResetBodySchema>): Promise<ApiResult<SessionResponse>> => api.post("/v1/auth/password-reset", body, { schema: sessionResponseSchema }),
    google: (body: In<typeof googleBodySchema>): Promise<ApiResult<SocialSessionResponse>> => api.post("/v1/auth/google", body, { schema: socialSessionResponseSchema }),
    /** Native iOS only. */
    apple: (body: In<typeof appleBodySchema>): Promise<ApiResult<SocialSessionResponse>> => api.post("/v1/auth/apple", body, { schema: socialSessionResponseSchema }),
    /** 204, also when the session had already ended. */
    logout: (): Promise<ApiResult<undefined>> => api.post("/v1/auth/logout", undefined, { schema: noContentSchema }),
  };
}
